(function(){'use strict';tinymce.PluginManager.add('shotto_math',function(editor,url){editor.on('PreInit',()=>editor.schema.addValidElements('span[class|style|contenteditable|title|dir|lang|id|role]'));
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function ready(){
  if(!window.ShottoMath?.compute)throw Error('Math runtime could not load. Reload the mathematics plugin.');
  const doc=editor.getDoc();
  if(!doc.getElementById('shotto-free-math-css')){const style=doc.createElement('style');style.id='shotto-free-math-css';style.textContent=window.ShottoFreeMathCSS;doc.head.append(style);}
  return {math:window.ShottoMath};
 }
 editor.on('init',()=>ready().catch(e=>editor.notificationManager.open({type:'error',text:e.message})));
 const guarded=fn=>()=>fn().catch(err=>editor.notificationManager.open({type:'error',text:err.message}));
 async function equation(target){const visual=editor.shottoEquationOwners?.get(target?.getAttribute('data-shotto-owner'))||editor.shottoVisual;if(visual)return visual.open({target});const {math}=await ready();editor.windowManager.open({title:'Shotto Equation',body:{type:'panel',items:[{type:'textarea',name:'latex',label:'LaTeX equation (double-click to edit later)'},{type:'htmlpanel',html:'<p>Fractions: \\frac{a}{b} · Roots: \\sqrt{x} · Integral: \\int_0^1 x^2 dx · Matrix: \\begin{pmatrix}1&amp;2\\\\3&amp;4\\end{pmatrix}</p>'}]},initialData:{latex:target?.getAttribute('data-latex')||'\\frac{-b+\\sqrt{b^2-4ac}}{2a}'},buttons:[{type:'cancel',text:'Cancel'},{type:'submit',text:target?'Update equation':'Insert equation',primary:true}],onSubmit:api=>{const latex=api.getData().latex.trim();if(!latex||latex.length>5000)return;const markup=`<span class="shotto-equation" contenteditable="false" data-latex="${esc(latex)}">${math.renderLatex(latex)}</span>`;editor.undoManager.transact(()=>target?editor.dom.setOuterHTML(target,markup):editor.insertContent(markup+'&nbsp;'));api.close();}});}
 async function calculate(){const {math}=await ready();let result='';editor.windowManager.open({title:'Shotto Calculator',body:{type:'panel',items:[{type:'input',name:'expression',label:'Expression (e.g. det([[1,2],[3,4]]))'},{type:'selectbox',name:'operation',label:'Operation',items:[{text:'Calculate',value:'evaluate'},{text:'Simplify',value:'simplify'},{text:'Derivative in x',value:'derivative'}]},{type:'textarea',name:'result',label:'Result'}]},initialData:{expression:'sqrt(144)+2^3',operation:'evaluate',result:''},buttons:[{type:'cancel',text:'Close'},{type:'custom',name:'calculate',text:'Calculate',primary:true},{type:'submit',text:'Insert result'}],onChange:api=>{result='';},onAction:async(api,d)=>{if(d.name!=='calculate')return;try{const v=api.getData(),answer=String(await math.compute(v.operation,v.expression));if(api.getData().expression===v.expression&&api.getData().operation===v.operation){result=answer;api.setData({result});}}catch(e){result='';api.setData({result:e.message});}},onSubmit:api=>{if(!result)return;editor.insertContent(esc(result));api.close();}});}
 async function graph(target){const {math}=await ready();let old={};try{old=JSON.parse(decodeURIComponent(target?.getAttribute('data-shotto-graph')||''));}catch{}editor.windowManager.open({title:'Shotto Function Graph',body:{type:'panel',items:[{type:'input',name:'expression',label:'y ='},{type:'input',name:'min',label:'Minimum x'},{type:'input',name:'max',label:'Maximum x'},{type:'htmlpanel',html:'<p>The graph is rendered offline and keeps its formula. Double-click it to edit.</p>'}]},initialData:{expression:old.expression||'sin(x)',min:String(old.min??-10),max:String(old.max??10)},buttons:[{type:'cancel',text:'Cancel'},{type:'submit',text:target?'Update graph':'Insert graph',primary:true}],onSubmit:async api=>{try{const d=api.getData(),min=Number(d.min),max=Number(d.max);if(!Number.isFinite(min)||!Number.isFinite(max)||min>=max)throw Error('Maximum x must be greater than minimum x.');const points=await math.compute('graph',d.expression,{min,max}),finite=points.map(p=>p[1]).filter(Number.isFinite).sort((a,b)=>a-b);if(!finite.length)throw Error('No real values in this range');let lo=finite[Math.floor(finite.length*.02)],hi=finite[Math.floor((finite.length-1)*.98)];if(lo===hi){lo--;hi++;}const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=600;const c=canvas.getContext('2d'),x=v=>60+(v-min)/(max-min)*880,y=v=>540-(v-lo)/(hi-lo)*460;c.fillStyle='white';c.fillRect(0,0,1000,600);c.fillStyle='#184b59';c.font='22px Arial';c.fillText('y = '+d.expression,60,40);c.strokeStyle='#dee7e7';c.lineWidth=1;for(let i=0;i<=10;i++){const xx=60+i*88,yy=80+i*46;c.beginPath();c.moveTo(xx,80);c.lineTo(xx,540);c.moveTo(60,yy);c.lineTo(940,yy);c.stroke();}c.fillText(String(min),60,575);c.fillText(String(max),900,575);c.save();c.beginPath();c.rect(60,80,880,460);c.clip();c.strokeStyle='#17617d';c.lineWidth=3;c.beginPath();let prev=null;for(const [xx,yy] of points){if(!Number.isFinite(yy)){prev=null;continue;}const px=x(xx),py=y(yy);if(prev!==null&&Math.abs(prev-py)<400)c.lineTo(px,py);else c.moveTo(px,py);prev=py;}c.stroke();c.restore();const meta=encodeURIComponent(JSON.stringify({expression:d.expression,min,max})),markup=`<img class="shotto-graph" src="${canvas.toDataURL()}" data-shotto-graph="${meta}" width="600" height="360" alt="${esc('Graph of '+d.expression)}">`;editor.undoManager.transact(()=>target?editor.dom.setOuterHTML(target,markup):editor.insertContent(markup));api.close();}catch(e){editor.notificationManager.open({type:'error',text:e.message});}}});}
 editor.on('DblClick',e=>{const q=e.target.closest?.('.shotto-equation[data-latex]'),g=e.target.closest?.('[data-shotto-graph]');if(q)guarded(()=>equation(q))();if(g)guarded(()=>graph(g))();});editor.ui.registry.addMenuButton('shotto_math',{text:'Mathematics',fetch:cb=>cb([{type:'menuitem',text:'Equation',onAction:guarded(()=>equation())},{type:'menuitem',text:'Calculator / simplify / derivative',onAction:guarded(calculate)},{type:'menuitem',text:'Function graph',onAction:guarded(()=>graph())}])});editor.ui.registry.addButton('shotto_equation',{text:'Equation',onAction:guarded(()=>equation())});return {getMetadata:()=>({name:'Shotto Free Mathematics 2.0.0'}),equation:guarded(()=>equation()),calculator:guarded(calculate),graph:guarded(()=>graph())};});})();
